    shot_seed(&mut world, first, seed);
    let seed = (0..=255)
        .find(|seed| {
            let mut dice = BattleDice::seeded([*seed; 32]);
            dice.two_d6() >= 10 && dice.two_d6() == 5
        })
        .unwrap();
    let expected_roll = BattleDice::seeded([seed; 32]).two_d6();
    shot_seed(&mut world, second, seed);
