    assert!(first_hit.target_impacts.iter().any(|impact| {
        impact
            .impact
            .phases
            .iter()
            .any(|phase| phase.destroyed_sections.contains(&BattleSection::RightLeg))
    }));
    let second_hit = report.attempts[1].collision.as_ref().unwrap();
